"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["25262"],{7990(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>m,frontMatter:()=>h,contentTitle:()=>c,toc:()=>d,assets:()=>p});var n=JSON.parse('{"id":"nhcx/v1/api/biometric/endpoints/biometric-faceauth-init","title":"Submit the face auth init","description":"Starts a face authentication on the ABDM proxy host and returns the txnId the rest of the face flow quotes.","source":"@site/docs/nhcx/v1/api/biometric/endpoints/biometric-faceauth-init.mdx","sourceDirName":"nhcx/v1/api/biometric/endpoints","slug":"/nhcx/v1/api/biometric/endpoints/biometric-faceauth-init","permalink":"/docs/main/docs/nhcx/v1/api/biometric/endpoints/biometric-faceauth-init","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the face auth init","sidebar_label":"Submit the face auth init","sidebar_class_name":"api-method api-method--post","description":"Starts a face authentication on the ABDM proxy host and returns the txnId the rest of the face flow quotes.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-biometric.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Get the biometric auth refresh token","permalink":"/docs/main/docs/nhcx/v1/api/biometric/endpoints/biometric-auth-refresh-token"},"next":{"title":"Submit the face auth capture PID","permalink":"/docs/main/docs/nhcx/v1/api/biometric/endpoints/biometric-faceauth-capture-pid"}}'),i=a(62540),o=a(43023),s=a(75064),r=JSON.parse('{"id":"biometric_faceauth_init","module":"ABHA biometric authentication","moduleId":"biometric","kind":"operation","method":"POST","path":"/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init","server":"https://apisbx.abdm.gov.in","servers":[{"url":"https://apisbx.abdm.gov.in","description":"Sandbox."}],"summary":"Face auth init","title":"Submit the face auth init","description":"Starts a face authentication on the ABDM proxy host and returns the `txnId` the rest of the face flow quotes.\\n\\n### Business purpose\\n\\nFace authentication is the method that works when fingerprint and iris do not. The capture happens on the patient\'s own phone, in the ABHA app, rather than on a hospital device. A case authenticated by fingerprint at admission can be authenticated by face at discharge, because the methods do not have to match across a case.\\n\\n### When to use\\n\\nWhen fingerprint and iris are not possible for the patient. Face authentication runs on a different host from the other two modalities and takes three calls and a QR code: this call, a QR code the patient scans, polling `Face auth capture PID`, then `Face auth verify`.\\n\\n### Preconditions\\n\\n- The ABDM session token on `Authorization`, with a fresh `REQUEST-ID` and the current `TIMESTAMP`.\\n- The request sent to the ABDM proxy host, under `/pmjay/sbxhcx/abdmproxy/abha/biometric/`.\\n- `scope` is `[\\"abha-enrol\\", \\"face-auth\\"]`.\\n- The patient has the ABHA app on a phone.\\n\\n### Postconditions\\n\\nReturns a `txnId`. Render `https://phrsbx.abdm.gov.in/face-auth?txnId=<txnId>` as a QR code. The patient scans it with the ABHA app and completes the face scan there.\\n\\n### Common mistakes\\n\\n- Sending it to the fingerprint host, which fails in a way that looks like a routing problem rather than a configuration one.\\n- Waiting for a callback. There is none, and the capture is polled.\\n- Treating face as optional. All three methods are mandatory to implement.\\n\\n### Best practices\\n\\n- Keep both biometric base paths in configuration.\\n- Record the `txnId` against the case as soon as it arrives.\\n\\n### Related scenario\\n\\nA patient authenticated by fingerprint at admission cannot be captured on the device at discharge. The desk calls this endpoint, shows the QR code built from the `txnId`, and the patient scans it with the ABHA app. The desk polls `Face auth capture PID` until the capture is complete, then calls `Face auth verify`.\\n\\n### Specification\\n\\nChapter [Biometric authentication](/docs/nhcx/v1/roles/provider/biometric-authentication) of the NHCX integration specification.","security":[],"headers":[{"name":"REQUEST-ID","required":true,"description":"`REQUEST-ID` is a fresh UUID that you generate for every call. Sending the same one twice is the mistake to avoid; generate it, do not copy it from an example.","example":"<uuid>","type":"string"},{"name":"TIMESTAMP","required":true,"description":"`TIMESTAMP` is the current time in UTC, ISO 8601 with milliseconds and a trailing `Z`, as in `2026-09-04T06:15:51.975Z`. A clock that has drifted will be refused, so take the time from the system rather than constructing it by hand. How to produce it in each language is at the end of this chapter.","example":"<iso timestamp>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"scope","type":"string[]","required":false,"description":"","encrypted":false}],"requestExample":{"scope":["abha-enrol","face-auth"]},"responses":[{"status":"200","description":"Returns a `txnId`."}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init \\\\\\n  --header \'REQUEST-ID: <uuid>\' \\\\\\n  --header \'TIMESTAMP: <iso timestamp>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"scope\\": [\\n    \\"abha-enrol\\",\\n    \\"face-auth\\"\\n  ]\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init \\\\\\n  --header \'REQUEST-ID: <uuid>\' \\\\\\n  --header \'TIMESTAMP: <iso timestamp>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"scope\\": [\\n    \\"abha-enrol\\",\\n    \\"face-auth\\"\\n  ]\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init\\",\\n    headers={\\n        \\"REQUEST-ID\\": \\"<uuid>\\",\\n        \\"TIMESTAMP\\": \\"<iso timestamp>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"scope\\": [\\n            \\"abha-enrol\\",\\n            \\"face-auth\\"\\n        ]\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/abdmproxy/abha/biometric/faceauth/init\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"REQUEST-ID\\": \\"<uuid>\\",\\n    \\"TIMESTAMP\\": \\"<iso timestamp>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"scope\\": [\\n      \\"abha-enrol\\",\\n      \\"face-auth\\"\\n    ]\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let h={title:"Submit the face auth init",sidebar_label:"Submit the face auth init",sidebar_class_name:"api-method api-method--post",description:"Starts a face authentication on the ABDM proxy host and returns the txnId the rest of the face flow quotes.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-biometric.yaml",generated:!0},c,p={},d=[];function u(e){return(0,i.jsx)(s.A,{operation:r})}function m(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}}}]);